const PALETTE = [
  "#FF0077", // Pink (0)
  "#00FFDD", // Cyan (1)
  "#AA00FF", // Purple (2)
  "#FFFF00", // Yellow (3)
  "#FFFFFF", // White (4)
  "#222222"  // Dark Gray (5)
];

const PADDLE_RADIUS = 120;
const PADDLE_WIDTH = 50;
const BLOCK_SIZE = 30;
const OVERFLOW_MAX = 100;
const MAX_PADDLE_SEGMENTS = 4;

// Helper to get a color from palette, or a random one
function getPaletteColor(index) {
  if (index === undefined) return GF.math.pick(PALETTE.slice(0, PALETTE.length - 2)); // Avoid white/black for blocks
  return PALETTE[index % PALETTE.length];
}

class Block {
  constructor(x, y, colorIndex, type = 'normal') {
    this.x = x;
    this.y = y;
    this.vx = 0;
    this.vy = 0;
    this.colorIndex = colorIndex;
    this.color = getPaletteColor(colorIndex);
    this.type = type; // 'normal', 'wildcard', 'bomb'
    this.size = BLOCK_SIZE;
    this.active = true;
  }

  draw(ctx) {
    if (!this.active) return;
    ctx.save();
    ctx.translate(this.x, this.y);

    // Draw shadow
    ctx.fillStyle = 'rgba(0,0,0,0.3)';
    GF.Draw.roundRect(ctx, -this.size / 2 + 3, -this.size / 2 + 3, this.size, this.size, 5, ctx.fillStyle);

    ctx.fillStyle = this.color;
    if (this.type === 'wildcard') {
      ctx.strokeStyle = PALETTE[4]; // White outline
      ctx.lineWidth = 3;
      GF.Draw.roundRect(ctx, -this.size / 2, -this.size / 2, this.size, this.size, 5, this.color);
      ctx.strokeRect(-this.size / 2, -this.size / 2, this.size, this.size);
      GF.Draw.text(ctx, '⭐', 0, 0, { size: this.size * 0.7, color: PALETTE[4] });
    } else if (this.type === 'bomb') {
      ctx.fillStyle = PALETTE[5]; // Dark Gray bomb body
      ctx.strokeStyle = PALETTE[0]; // Pink outline
      ctx.lineWidth = 3;
      GF.Draw.roundRect(ctx, -this.size / 2, -this.size / 2, this.size, this.size, 5, PALETTE[5]);
      ctx.strokeRect(-this.size / 2, -this.size / 2, this.size, this.size);
      GF.Draw.text(ctx, '💥', 0, 0, { size: this.size * 0.7, color: PALETTE[4] });
    } else {
      GF.Draw.roundRect(ctx, -this.size / 2, -this.size / 2, this.size, this.size, 5, this.color);
    }
    ctx.restore();
  }
}

const game = new GF.Game({
  id: 'color-cascade',
  title: 'Color Cascade',
  width: 960,
  height: 540,
  palette: PALETTE,
  background: PALETTE[5]
});

let paddle = {
  x: game.W / 2,
  y: game.H - PADDLE_RADIUS / 2,
  rotation: 0, // radians
  segments: [],
  numSegments: 3
};

let blocks = [];
let overflow = 0;
let combo = 0;
let lastCatchTime = 0;
let nextBlockTime = 0;
let fallSpeed = 70; // pixels/sec
let blockSpawnInterval = 1.5; // seconds
let paddleRotationSpeed = 3;
let backgroundPulse = 0;

function resetGameVariables() {
  paddle.rotation = 0;
  paddle.numSegments = 3;
  paddle.segments = [];
  blocks = [];
  overflow = 0;
  combo = 0;
  lastCatchTime = 0;
  nextBlockTime = 0;
  fallSpeed = 70;
  blockSpawnInterval = 1.5;
  createPaddleSegments();
}

function createPaddleSegments() {
  paddle.segments = [];
  let availableColors = [0, 1, 2, 3]; // Indices for palette, excluding white/black
  // Shuffle available colors to make paddle segments random
  for (let i = availableColors.length - 1; i > 0; i--) {
    const j = Math.floor(game.rng() * (i + 1));
    [availableColors[i], availableColors[j]] = [availableColors[j], availableColors[i]];
  }

  for (let i = 0; i < paddle.numSegments; i++) {
    const colorIndex = availableColors[i % availableColors.length]; // Cycle through available colors
    paddle.segments.push({ colorIndex, color: getPaletteColor(colorIndex) });
  }
}

function spawnBlock() {
  const x = GF.math.rand(BLOCK_SIZE, game.W - BLOCK_SIZE);
  const y = -BLOCK_SIZE;
  let colorIndex = GF.math.pick(paddle.segments).colorIndex;
  let type = 'normal';

  // Difficulty progression for special blocks
  if (game.time > 20 && game.rng() < 0.1) {
    type = GF.math.pick(['wildcard', 'bomb']);
    GF.Sfx.beep({ freq: 800, dur: 0.05, type: 'sine', vol: 0.2 });
  }

  blocks.push(new Block(x, y, colorIndex, type));
}

game.add('play', {
  init() {
    resetGameVariables();
  },
  reset() {
    resetGameVariables();
  },
  update(dt) {
    // Difficulty ramp
    fallSpeed = 70 + game.time * 2;
    blockSpawnInterval = Math.max(0.5, 1.5 - game.time * 0.01);

    const newNumSegments = Math.min(MAX_PADDLE_SEGMENTS, 3 + Math.floor(game.time / 30));
    if (paddle.numSegments !== newNumSegments) {
      paddle.numSegments = newNumSegments;
      createPaddleSegments();
    }

    // Rotate paddle
    let rotationInput = 0;
    if (game.input.keys['ArrowLeft'] || game.input.keys['KeyA']) {
      rotationInput = -1;
    }
    if (game.input.keys['ArrowRight'] || game.input.keys['KeyD']) {
      rotationInput = 1;
    }
    // Mouse input for paddle rotation
    if (game.input.pointer.down) {
      const mouseDeltaX = game.input.pointer.x - game.W / 2;
      const rotationFactor = 0.005; // Adjust sensitivity
      paddle.rotation += mouseDeltaX * rotationFactor * dt * 60; // Scale with dt for consistent feel
    }

    if (rotationInput !== 0) {
      paddle.rotation += rotationInput * paddleRotationSpeed * dt;
      // Only play sound if actively rotating via keys
      GF.Sfx.beep({ freq: 200, dur: 0.01, type: 'sine', vol: 0.02, delay: 0 });
    }

    paddle.rotation %= GF.math.TAU;

    // Spawn blocks
    nextBlockTime -= dt;
    if (nextBlockTime <= 0) {
      spawnBlock();
      nextBlockTime = blockSpawnInterval;
    }

    // Update blocks
    for (let i = blocks.length - 1; i >= 0; i--) {
      const block = blocks[i];
      if (!block.active) continue;

      block.y += fallSpeed * dt;

      // Check for collision with paddle
      const dx = block.x - paddle.x;
      const dy = block.y - paddle.y;
      const distToPaddleCenter = GF.math.dist(block.x, block.y, paddle.x, paddle.y);

      if (distToPaddleCenter < PADDLE_RADIUS + BLOCK_SIZE / 2) {
        // Check if block is below the paddle's top edge (to prevent catching blocks from above)
        if (block.y > paddle.y - PADDLE_WIDTH / 2) {
          // Calculate angle relative to paddle's current rotation
          let angle = Math.atan2(dy, dx);
          // Normalize angle to be relative to paddle's 0 rotation point, then adjust for paddle's actual rotation
          // The paddle's segments are drawn starting from -TAU/4 (top-left) to 3*TAU/4 (top-right)
          // So, we need to adjust the block's angle to match this segment layout.
          // A block at the top (0, -R) would be at angle -PI/2 or 3PI/2. Our segments start from -PI/2.
          // The paddle's rotation rotates the entire segment structure.
          // So, to find which segment the block hits, we need to 'un-rotate' the block's position by paddle.rotation.
          let relativeAngle = (angle - paddle.rotation + GF.math.TAU) % GF.math.TAU;

          // Adjust relativeAngle to match segment indexing. Segments are drawn from -TAU/4 to 3*TAU/4.
          // We want 0 to be the start of the first segment. If segments start at -TAU/4, then
          // an angle of -TAU/4 should map to segment 0.
          // Adding TAU/4 shifts the range so that the first segment starts at 0.
          relativeAngle = (relativeAngle + GF.math.TAU / 4 + GF.math.TAU) % GF.math.TAU;

          const segmentAngle = GF.math.TAU / paddle.numSegments;
          const segmentIndex = Math.floor(relativeAngle / segmentAngle);

          if (segmentIndex >= 0 && segmentIndex < paddle.numSegments) {
            const targetSegment = paddle.segments[segmentIndex];

            let matched = false;
            if (block.type === 'wildcard') {
              game.addScore(20);
              matched = true;
              game.burst(block.x, block.y, { count: 15, speed: 150, size: 8, life: 0.8, colors: [PALETTE[4], targetSegment.color], spread: GF.math.TAU });
              GF.Sfx.beep({ freq: 900, to: 1200, dur: 0.1, type: 'triangle', vol: 0.3 });
              game.flash(PALETTE[4], 0.3);
            } else if (block.type === 'bomb') {
              game.addScore(25);
              matched = true;
              game.burst(block.x, block.y, { count: 30, speed: 200, size: 10, life: 1, colors: [PALETTE[0], PALETTE[3], PALETTE[4]], spread: GF.math.TAU });
              game.shake(10, 0.4);
              game.hitStop(0.15);
              GF.Sfx.noise({ dur: 0.2, vol: 0.5, freq: 200 });
              GF.Sfx.beep({ freq: 100, to: 50, dur: 0.3, type: 'sawtooth', vol: 0.4 });
              // Clear nearby blocks
              for (const otherBlock of blocks) {
                if (otherBlock.active && GF.math.dist(block.x, block.y, otherBlock.x, otherBlock.y) < BLOCK_SIZE * 3) {
                  otherBlock.active = false;
                  game.burst(otherBlock.x, otherBlock.y, { count: 8, speed: 100, size: 5, life: 0.5, colors: [otherBlock.color] });
                }
              }
            } else if (targetSegment.colorIndex === block.colorIndex) {
              matched = true;
              game.addScore(10 + combo * 2);
              game.burst(block.x, block.y, { count: 10, speed: 100, size: 6, life: 0.5, colors: [block.color] });
              game.flash(block.color, 0.2);
              GF.Sfx.beep({ freq: 660, to: 880, dur: 0.08, type: 'sine', vol: 0.2 });

              const now = game.time;
              if (now - lastCatchTime < 0.5) {
                combo++;
                if (combo > 1) {
                  game.hitStop(0.05);
                  GF.Sfx.beep({ freq: 1000 + combo * 50, dur: 0.05, type: 'triangle', vol: 0.3 });
                }
              } else {
                combo = 1;
              }
              lastCatchTime = now;
            }

            if (matched) {
              block.active = false;
            } else {
              // Mismatch
              overflow += 10;
              game.burst(block.x, block.y, { count: 10, speed: 80, size: 5, life: 0.5, colors: [PALETTE[5]], spread: GF.math.TAU }); // Dark splatter
              GF.Sfx.noise({ dur: 0.1, vol: 0.3, freq: 500 });
              game.flash(PALETTE[0], 0.4); // Red flash
              block.active = false;
              combo = 0; // Break combo on mismatch
              if (overflow >= OVERFLOW_MAX * 0.7) game.shake(3, 0.1);
            }
          }
        }
      }

      // Check for missed blocks (off screen bottom)
      if (block.y > game.H + BLOCK_SIZE / 2) {
        if (block.active) {
          overflow += 15;
          game.burst(block.x, block.y, { count: 10, speed: 80, size: 5, life: 0.5, colors: [PALETTE[5]], spread: GF.math.TAU }); // Dark splatter
          GF.Sfx.noise({ dur: 0.1, vol: 0.3, freq: 500 });
          game.flash(PALETTE[0], 0.4); // Red flash
          combo = 0; // Break combo on miss
          if (overflow >= OVERFLOW_MAX * 0.7) game.shake(3, 0.1);
        }
        block.active = false;
      }
    }

    blocks = blocks.filter(b => b.active);

    // Background pulse
    backgroundPulse = (Math.sin(game.time * 2) * 0.5 + 0.5) * 0.05; // 0 to 0.05

    // Check for game over
    if (overflow >= OVERFLOW_MAX) {
      game.gameOver({ message: 'OVERFLOW!' });
      GF.Sfx.melody([[392, 0.12], [330, 0.12], [262, 0.2]], { type: 'sawtooth', vol: 0.5 });
      game.shake(15, 0.6);
    }
  },
  draw(ctx) {
    // Background gradient with subtle pulse
    const gradient = ctx.createLinearGradient(0, 0, game.W, game.H);
    // The issue was here: GF.math.lerpColor is not a function in the provided engine.
    // Instead, we should lerp the values of the color components (R, G, B) and then convert back to hex.
    // For simplicity and to fix the error, I'll lerp between two palette colors directly.
    const baseColor = PALETTE[5]; // Dark Gray
    const pulseColor = PALETTE[2]; // Purple
    const mixedColor = `rgb(${Math.round(GF.math.lerp(parseInt(baseColor.substring(1,3), 16), parseInt(pulseColor.substring(1,3), 16), backgroundPulse))},` +
                       `${Math.round(GF.math.lerp(parseInt(baseColor.substring(3,5), 16), parseInt(pulseColor.substring(3,5), 16), backgroundPulse))},` +
                       `${Math.round(GF.math.lerp(parseInt(baseColor.substring(5,7), 16), parseInt(pulseColor.substring(5,7), 16), backgroundPulse))})`;

    gradient.addColorStop(0, baseColor);
    gradient.addColorStop(1, mixedColor);
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, game.W, game.H);

    // Draw paddle
    ctx.save();
    ctx.translate(paddle.x, paddle.y);
    ctx.rotate(paddle.rotation);
    const segmentAngle = GF.math.TAU / paddle.numSegments;

    // Draw paddle segments with inner and outer rings for depth
    for (let i = 0; i < paddle.numSegments; i++) {
      const startAngle = i * segmentAngle - GF.math.TAU / 4; // Start from top-left
      const endAngle = (i + 1) * segmentAngle - GF.math.TAU / 4;

      // Outer ring
      ctx.beginPath();
      ctx.arc(0, 0, PADDLE_RADIUS + PADDLE_WIDTH / 2 + 5, startAngle, endAngle);
      ctx.lineWidth = PADDLE_WIDTH + 10;
      ctx.strokeStyle = paddle.segments[i].color + '44'; // Semi-transparent outer glow
      ctx.stroke();

      // Main segment
      ctx.beginPath();
      ctx.arc(0, 0, PADDLE_RADIUS + PADDLE_WIDTH / 2, startAngle, endAngle);
      ctx.lineWidth = PADDLE_WIDTH;
      ctx.strokeStyle = paddle.segments[i].color;
      ctx.stroke();

      // Inner ring (darker for depth)
      ctx.beginPath();
      ctx.arc(0, 0, PADDLE_RADIUS + PADDLE_WIDTH / 2 - 5, startAngle, endAngle);
      ctx.lineWidth = PADDLE_WIDTH - 10;
      ctx.strokeStyle = paddle.segments[i].color + '88'; // Slightly darker inner
      ctx.stroke();
    }
    ctx.restore();

    // Draw blocks
    for (const block of blocks) {
      block.draw(ctx);
    }

    // Draw combo meter
    if (combo > 0) {
      GF.Draw.text(ctx, `COMBO x${combo}`, game.W / 2, game.H / 2 - 100, {
        size: 30 + combo * 2, // Larger for bigger combos
        color: PALETTE[3],
        weight: 'bold',
        align: 'center'
      });
    }

    // Draw overflow meter
    const overflowFillRatio = overflow / OVERFLOW_MAX;
    const overflowHeight = overflowFillRatio * (game.H * 0.8);
    const meterX = game.W - 50;
    const meterY = game.H * 0.1;
    const meterWidth = 30;
    const meterHeight = game.H * 0.8;
    const borderRadius = 10;

    // Background for overflow meter
    GF.Draw.roundRect(ctx, meterX, meterY, meterWidth, meterHeight, borderRadius, PALETTE[2] + '33');

    // Fill for overflow meter, color changes with criticality
    // The issue was here: GF.math.lerpColor is not a function in the provided engine.
    // Manually lerp RGB components.
    const color1 = PALETTE[1]; // Cyan
    const color2 = PALETTE[0]; // Pink

    const r = Math.round(GF.math.lerp(parseInt(color1.substring(1,3), 16), parseInt(color2.substring(1,3), 16), overflowFillRatio));
    const g = Math.round(GF.math.lerp(parseInt(color1.substring(3,5), 16), parseInt(color2.substring(3,5), 16), overflowFillRatio));
    const b = Math.round(GF.math.lerp(parseInt(color1.substring(5,7), 16), parseInt(color2.substring(5,7), 16), overflowFillRatio));
    const overflowColor = `rgb(${r},${g},${b})`;

    GF.Draw.roundRect(ctx, meterX, meterY + meterHeight - overflowHeight, meterWidth, overflowHeight, borderRadius, overflowColor);

    // Draw score and best score
    GF.Draw.text(ctx, String(game.score), game.W / 2, 44, { size: 34, color: PALETTE[4], weight: 'bold' });
    GF.Draw.text(ctx, 'BEST ' + game.best, game.W - 20, 30, { size: 15, color: PALETTE[4] + 'AA', align: 'right', weight: '700' });

    // Vignette
    GF.Draw.vignette(ctx, game.W, game.H, 0.4);
  }
});

game.titleScreen({ subtitle: 'Rotate paddle with A/D or Left/Right arrows / mouse' });
